package dev.pocketengine.ui;

import dev.pocketengine.features.controlplane.WorkProfile;
import dev.pocketengine.runtime.models.ModelTargetRef;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

/** UI projection only, not visual acceptance or native source/permission admission. */
public final class WorkProfileDraftsTest {
    private JSONObject draft()throws Exception{return WorkProfile.definition("draft-profile",1,"Original editor");}
    @Test public void leavingChecksTheVisibleNameAndExactReferenceDraftWithoutMutatingTheSavedDefinition()throws Exception{
        JSONObject saved=draft();assertTrue(WorkProfileDrafts.changed(saved,null,"Original editor"));assertFalse(WorkProfileDrafts.changed(saved,saved,"Original editor"));assertTrue(WorkProfileDrafts.changed(saved,saved,"Changed name"));JSONObject selected=WorkProfileDrafts.withModel(saved,"MAIN",ModelTargetRef.exact("api-a","main").toJson());assertTrue(WorkProfileDrafts.changed(selected,saved,"Original editor"));assertEquals("Original editor",saved.getString("name"));assertEquals(0,saved.getJSONObject("modelPolicies").length());
    }
    @Test public void recoveryEntryOnlyBelongsToAnExplicitPrivateOwnerAssistantWithRetainedProfile()throws Exception{
        JSONObject task=new JSONObject().put("id","original-task").put("kind","assistant").put("actorId","owner").put("spaceId","private");assertFalse(WorkProfileDrafts.originalOwnerTask(task));task.put("workProfileIntent",new JSONObject());assertTrue(WorkProfileDrafts.originalOwnerTask(task));for(String field:new String[]{"sourceLearningJob","teamAssignment","teamWriteScope"}){JSONObject foreign=new JSONObject(task.toString()).put(field,new JSONObject());assertFalse(WorkProfileDrafts.originalOwnerTask(foreign));}for(String origin:new String[]{"channel","group","paired_device","team_assignment"})assertFalse(WorkProfileDrafts.originalOwnerTask(new JSONObject(task.toString()).put("origin",new JSONObject().put("kind",origin))));assertFalse(WorkProfileDrafts.originalOwnerTask(new JSONObject(task.toString()).put("spaceId","group")));assertFalse(WorkProfileDrafts.originalOwnerTask(new JSONObject(task.toString()).put("actorId","external")));assertFalse(WorkProfileDrafts.originalOwnerTask(new JSONObject(task.toString()).put("kind","phone")));task.remove("workProfileIntent");task.put("workProfileRef",new JSONObject());assertTrue(WorkProfileDrafts.originalOwnerTask(task));
    }
    @Test public void pluginBindingComparisonUsesExactJsonValuesRatherThanJvmNumberWrapperTypes()throws Exception{
        JSONObject row=new JSONObject().put("id","plugin-a").put("installationId","original-install").put("stateRevision",2L).put("manifestDigest","a".repeat(64)).put("enabled",true).put("tools",new JSONArray().put(new JSONObject().put("name","read").put("granted",true)).put(new JSONObject().put("name","write").put("granted",true)));JSONObject selected=WorkProfileDrafts.withPluginTool(draft(),row,"read",true);assertTrue(WorkProfileDrafts.hasPluginTool(selected,row,"read"));JSONObject next=WorkProfileDrafts.withPluginTool(selected,row,"write",true);assertTrue(WorkProfileDrafts.hasPluginTool(next,row,"read"));assertTrue(WorkProfileDrafts.hasPluginTool(next,row,"write"));assertEquals(2,next.getJSONArray("pluginRefs").getJSONObject(0).getJSONArray("tools").length());
    }
    @Test public void selectedAssetChoicesBecomeExactReferencesWithoutCopyingSourceBodiesOrTokens()throws Exception{
        JSONObject row=new JSONObject().put("id","skill-a").put("revision",1).put("digest","a".repeat(64)).put("body","DO_NOT_COPY").put("token","DO_NOT_COPY");JSONObject before=draft(),next=WorkProfileDrafts.withReference(before,"skillRefs",WorkProfileDrafts.skillReference(row),true);assertEquals(0,before.getJSONArray("skillRefs").length());assertEquals(1,next.getJSONArray("skillRefs").length());assertFalse(next.toString().contains("DO_NOT_COPY"));assertFalse(next.getJSONArray("skillRefs").getJSONObject(0).getBoolean("optional"));next=WorkProfileDrafts.withOptional(next,"skillRefs","skill-a",true);assertTrue(next.getJSONArray("skillRefs").getJSONObject(0).getBoolean("optional"));assertEquals(0,WorkProfileDrafts.withReference(next,"skillRefs",WorkProfileDrafts.skillReference(row),false).getJSONArray("skillRefs").length());
    }
    @Test public void pluginToolSelectionCannotTurnAnUnreviewedGrantOrDisabledInstallationIntoAChoice()throws Exception{
        JSONObject row=new JSONObject().put("id","plugin-a").put("installationId","install-a").put("stateRevision",2).put("manifestDigest","a".repeat(64)).put("enabled",true).put("tools",new JSONArray().put(new JSONObject().put("name","read").put("granted",true)).put(new JSONObject().put("name","write").put("granted",false))).put("token","DO_NOT_COPY");assertThrows(SecurityException.class,()->WorkProfileDrafts.withPluginTool(draft(),row,"write",true));JSONObject chosen=WorkProfileDrafts.withPluginTool(draft(),row,"read",true);assertTrue(WorkProfileDrafts.hasPluginTool(chosen,"plugin-a","read"));assertFalse(chosen.toString().contains("DO_NOT_COPY"));assertFalse(chosen.toString().contains("granted"));row.put("enabled",false);assertThrows(SecurityException.class,()->WorkProfileDrafts.withPluginTool(draft(),row,"read",true));assertEquals(0,WorkProfileDrafts.withPluginTool(chosen,row,"read",false).getJSONArray("pluginRefs").length());
    }
    @Test public void modelChoicesAreOriginalEnabledConnectionsExactGroupRevisionOrUsableSelectedAccountOnly()throws Exception{
        JSONObject api=new JSONObject().put("connections",new JSONArray().put(new JSONObject().put("id","api-a").put("name","Original").put("model","main").put("enabled",true).put("apiKey","DO_NOT_COPY")).put(new JSONObject().put("id","api-b").put("name","Disabled").put("model","wrong").put("enabled",false)));JSONObject models=new JSONObject().put("available",true).put("api",api).put("groups",new JSONObject().put("groups",new JSONArray().put(new JSONObject().put("groupId","coding").put("revision",3).put("name","Coding"))));JSONObject accounts=new JSONObject().put("available",true).put("selectedModelUsable",false).put("selectedModelRef",new JSONObject().put("accountId","owner").put("accountVersion",2).put("modelId","account-model"));JSONObject choices=new JSONObject().put("sections",new JSONObject().put("models",models).put("accounts",accounts));JSONArray rows=WorkProfileDrafts.modelChoices(choices);assertEquals(2,rows.length());assertEquals(3,rows.getJSONObject(1).getJSONObject("reference").getLong("groupRevision"));assertFalse(rows.toString().contains("DO_NOT_COPY"));accounts.put("selectedModelUsable",true);rows=WorkProfileDrafts.modelChoices(choices);assertEquals(3,rows.length());assertEquals("account:owner",rows.getJSONObject(2).getJSONObject("reference").getString("connectionId"));
    }
    @Test public void editorModelPoliciesCannotInventUnsupportedRolesOrFallbackTargets()throws Exception{
        JSONObject ref=ModelTargetRef.exact("api-a","main").toJson(),before=draft();JSONObject next=WorkProfileDrafts.withModel(before,"MAIN",ref);assertEquals(0,before.getJSONObject("modelPolicies").length());assertEquals("api-a",next.getJSONObject("modelPolicies").getJSONObject("MAIN").getString("connectionId"));assertEquals("api-a",WorkProfileDrafts.withModel(before,"MEMBER.review",ref).getJSONObject("modelPolicies").getJSONObject("MEMBER.review").getString("connectionId"));assertThrows(IllegalArgumentException.class,()->WorkProfileDrafts.withModel(before,"MEMBER.review.extra",ref));assertThrows(IllegalArgumentException.class,()->WorkProfileDrafts.withModel(before,"SUMMARY",new JSONObject(ref.toString()).put("token","no")));
    }
    @Test public void stalePluginAndSkillReferencesNeverAppearAsCurrentChoicesOrCarryOldToolsAcrossANewBinding()throws Exception{
        JSONObject row=new JSONObject().put("id","plugin-a").put("installationId","first-install").put("stateRevision",1).put("manifestDigest","a".repeat(64)).put("enabled",true).put("tools",new JSONArray().put(new JSONObject().put("name","read").put("granted",true)).put(new JSONObject().put("name","write").put("granted",true)));JSONObject selected=WorkProfileDrafts.withPluginTool(draft(),row,"read",true);row.put("installationId","new-install").put("stateRevision",2);assertFalse(WorkProfileDrafts.hasPluginTool(selected,row,"read"));JSONObject next=WorkProfileDrafts.withPluginTool(selected,row,"write",true);assertFalse(WorkProfileDrafts.hasPluginTool(next,"plugin-a","read"));assertTrue(WorkProfileDrafts.hasPluginTool(next,row,"write"));assertEquals("first-install",selected.getJSONArray("pluginRefs").getJSONObject(0).getString("installationId"));JSONObject skill=new JSONObject().put("id","skill-a").put("revision",1).put("digest","a".repeat(64));JSONObject old=WorkProfileDrafts.withReference(draft(),"skillRefs",WorkProfileDrafts.skillReference(skill),true);skill.put("revision",2);assertFalse(WorkProfileDrafts.matchesReference(old,"skillRefs",WorkProfileDrafts.skillReference(skill)));assertEquals(1,WorkProfileDrafts.withReference(old,"skillRefs",WorkProfileDrafts.skillReference(skill),true).getJSONArray("skillRefs").length());
    }
    @Test public void sourceReadyIsNotRunnableWhenModelsArePartialOrConfigurationHasNotBeenApplied()throws Exception{
        JSONObject view=new JSONObject().put("ready",true).put("modelPolicies",new JSONObject()).put("items",new JSONArray());assertFalse(WorkProfileDrafts.runnable(view));view.getJSONObject("modelPolicies").put("MAIN",new JSONObject()).put("SUMMARY",new JSONObject());assertTrue(WorkProfileDrafts.runnable(view));view.getJSONArray("items").put(new JSONObject().put("kind","target:remote_harness").put("included",true));assertFalse(WorkProfileDrafts.runnable(view));view.getJSONArray("items").getJSONObject(0).put("included",false);assertTrue(WorkProfileDrafts.runnable(view));view.put("ready",false);assertFalse(WorkProfileDrafts.runnable(view));
    }
    @Test public void concurrencyEditorOnlyRequestsBoundedTaskLimitsAndDoesNotMutateTheOriginalDefinition()throws Exception{
        JSONObject original=draft(),one=WorkProfileDrafts.withModelConcurrency(original,1);assertEquals(0,original.getJSONObject("resourcePreferences").length());assertEquals(1,one.getJSONObject("resourcePreferences").getInt("maxConcurrentModelCalls"));assertThrows(IllegalArgumentException.class,()->WorkProfileDrafts.withModelConcurrency(one,3));assertThrows(IllegalArgumentException.class,()->WorkProfileDrafts.withModelConcurrency(one,0));assertEquals(0,WorkProfileDrafts.withModelConcurrency(one,null).getJSONObject("resourcePreferences").length());JSONObject view=new JSONObject().put("ready",true).put("modelPolicies",new JSONObject().put("MAIN",new JSONObject()).put("SUMMARY",new JSONObject())).put("items",new JSONArray()).put("resourcePreferences",one.getJSONObject("resourcePreferences"));assertTrue(WorkProfileDrafts.runnable(view));assertFalse(view.optBoolean("configurationApplied"));
    }
    @Test public void instructionEditorKeepsExactGuidanceSeparateFromExecutableSkillSelection()throws Exception {
        JSONObject original=draft(),ref=new JSONObject().put("id","guidance").put("revision",2).put("digest","a".repeat(64)).put("optional",false);
        JSONObject selected=WorkProfileDrafts.withReference(original,"instructionRefs",ref,true);assertEquals(0,original.getJSONArray("instructionRefs").length());
        assertEquals(1,selected.getJSONArray("instructionRefs").length());assertEquals(0,selected.getJSONArray("skillRefs").length());
        assertTrue(WorkProfileDrafts.matchesReference(selected,"instructionRefs",ref));
        JSONObject optional=WorkProfileDrafts.withOptional(selected,"instructionRefs","guidance",true);assertTrue(optional.getJSONArray("instructionRefs").getJSONObject(0).getBoolean("optional"));
        assertEquals(0,WorkProfileDrafts.withoutReference(optional,"instructionRefs","guidance").getJSONArray("instructionRefs").length());
        JSONObject review=new JSONObject().put("ready",true).put("modelPolicies",new JSONObject().put("MAIN",new JSONObject()).put("SUMMARY",new JSONObject()))
            .put("items",new JSONArray().put(new JSONObject().put("kind","instruction").put("included",true)));
        assertTrue(WorkProfileDrafts.runnable(review));assertFalse(review.optBoolean("configurationApplied"));
        review.getJSONArray("items").put(new JSONObject().put("kind","team").put("included",true));assertFalse(WorkProfileDrafts.runnable(review));
    }
    @Test public void nativeProjectPresenceOnlyEnablesLocalMemberAndTeamPreparationNeverTargetApplication()throws Exception {
        JSONObject view=new JSONObject().put("ready",true).put("modelPolicies",new JSONObject().put("MAIN",new JSONObject()).put("SUMMARY",new JSONObject()).put("_GLOBAL",new JSONObject()).put("MEMBER.review",new JSONObject()))
            .put("items",new JSONArray().put(new JSONObject().put("kind","team").put("included",true)));
        assertFalse(WorkProfileDrafts.runnable(view));assertTrue(WorkProfileDrafts.runnable(view,true));assertFalse(view.optBoolean("configurationApplied"));assertFalse(view.optBoolean("executionAuthorized"));
        view.getJSONArray("items").put(new JSONObject().put("kind","target:remote_harness").put("included",true));assertFalse(WorkProfileDrafts.runnable(view,true));
        view.getJSONArray("items").getJSONObject(1).put("included",false);assertTrue(WorkProfileDrafts.runnable(view,true));
    }
    @Test public void nativeTeamTemplateChoiceCopiesOnlyExactReferenceAndKeepsAllOtherDraftPolicies()throws Exception {
        JSONObject before=WorkProfileDrafts.withModel(draft(),"MEMBER.review",ModelTargetRef.exact("api-a","review").toJson());
        JSONObject row=new JSONObject().put("id","native-team").put("digest","a".repeat(64)).put("members",new JSONArray()).put("token","DO_NOT_COPY");
        JSONObject selected=WorkProfileDrafts.withTeamTemplate(before,row);assertTrue(before.isNull("teamTemplateRef"));assertEquals(3,selected.getJSONObject("teamTemplateRef").length());assertFalse(selected.toString().contains("DO_NOT_COPY"));
        JSONObject removed=WorkProfileDrafts.withTeamTemplate(selected,null);assertTrue(removed.isNull("teamTemplateRef"));assertTrue(removed.getJSONObject("modelPolicies").has("MEMBER.review"));
        assertFalse(WorkProfileDrafts.withoutMemberModel(removed,"MEMBER.review").getJSONObject("modelPolicies").has("MEMBER.review"));assertThrows(IllegalArgumentException.class,()->WorkProfileDrafts.withoutMemberModel(removed,"MAIN"));
    }
    @Test public void optionalRelayEditingNeverSelectsAccountPlansOrChangesRequiredMainAndSummary()throws Exception {
        JSONObject accounts=new JSONObject().put("available",true).put("selectedModelUsable",true).put("selectedModelRef",new JSONObject().put("accountId","owner").put("accountVersion",2).put("modelId","account-model"));
        JSONObject choices=new JSONObject().put("sections",new JSONObject().put("accounts",accounts));assertEquals(1,WorkProfileDrafts.modelChoices(choices,"MAIN").length());assertEquals(0,WorkProfileDrafts.modelChoices(choices,"RELAY").length());
        JSONObject ref=ModelTargetRef.exact("api-a","model-a").toJson(),main=WorkProfileDrafts.withModel(draft(),"MAIN",ref),both=WorkProfileDrafts.withModel(main,"SUMMARY",ref),relay=WorkProfileDrafts.withModel(both,"RELAY",ref);
        assertEquals(2,both.getJSONObject("modelPolicies").length());assertEquals(3,relay.getJSONObject("modelPolicies").length());assertEquals(2,WorkProfileDrafts.withoutRelayModel(relay).getJSONObject("modelPolicies").length());
        JSONObject review=new JSONObject().put("ready",true).put("modelPolicies",relay.getJSONObject("modelPolicies")).put("items",new JSONArray());assertTrue(WorkProfileDrafts.runnable(review));review.getJSONObject("modelPolicies").put("MEMBER.review",ref);assertFalse(WorkProfileDrafts.runnable(review));
    }
}
